mapper.select:
SELECT ss.id, ss.category_id AS categoryId, ss.name, ss.brief, ss.address, ss.longitude, ss.latitude, ss.images, ss.map_icon_url AS mapIconUrl, ss.cover_media_id AS coverMediaId, ss.trigger_radius_m AS triggerRadiusM, ss.trigger_enabled AS triggerEnabled, ss.audio_media_id AS audioMediaId, ss.audio_media_url AS audioMediaUrl, ss.opening_hours AS openingHours, ss.sort_no AS sortNo, ss.status, ss.created_at AS createdAt, ss.updated_at AS updatedAt, sc.name AS categoryName FROM scenic_spot ss LEFT JOIN scenic_category sc ON ss.category_id = sc.id WHERE 1 = 1
AND ss.name LIKE CONCAT('%',#{scenicSpot.name},'%')
AND ss.category_id = #{scenicSpot.categoryId}
AND ss.status = #{scenicSpot.status}
AND ss.deleted = #{scenicSpot.deleted}
ORDER BY ss.sort_no ASC

